# --- 4. Клавиатуры ---

MAIN_MENU_KEYBOARD = ReplyKeyboardMarkup(
    keyboard=[
        [KeyboardButton(text="Общий"), KeyboardButton(text="Медицинский")],
        [KeyboardButton(text="Юридический"), KeyboardButton(text="Познакомиться с терминами")], 
        [KeyboardButton(text="Помощь")]
    ],
    resize_keyboard=True,
    input_field_placeholder="Выберите раздел..."
)

# --- 5. Вспомогательная функция для пагинации терминов (КНОПКИ) ---

def get_terms_page_keyboard(current_page: int) -> InlineKeyboardMarkup:
    """Генерирует клавиатуру с терминами-кнопками и навигацией."""
    
    start_index = (current_page - 1) * TERMS_PER_PAGE
    end_index = start_index + TERMS_PER_PAGE
    current_terms_slice = TERMS_KEYS[start_index:end_index]
    
    builder = InlineKeyboardBuilder()
    
    # 1. Добавляем кнопки с названиями терминов
    for term in current_terms_slice:
        # Callback data будет 'term:<НазваниеТермина>'
        builder.row(InlineKeyboardButton(text=term, callback_data=f"term:{term}"))

    # 2. Добавляем навигацию по страницам
    prev_page = current_page - 1
    next_page = current_page + 1
    
    # Ряд с навигационными кнопками
    nav_buttons = []
    
    if current_page > 1:
        nav_buttons.append(InlineKeyboardButton(text="←", callback_data=f"terms_page:{prev_page}"))
    else:
        nav_buttons.append(InlineKeyboardButton(text=" ", callback_data="ignore")) 
        
    nav_buttons.append(InlineKeyboardButton(text="Вернуться в меню", callback_data="terms_exit"))
    
    if current_page < TOTAL_PAGES:
        nav_buttons.append(InlineKeyboardButton(text="→", callback_data=f"terms_page:{next_page}"))
    else:
        nav_buttons.append(InlineKeyboardButton(text=" ", callback_data="ignore"))
    
    builder.row(*nav_buttons)
    
    return builder.as_markup()

async def send_terms_page(message: Message, state: FSMContext, page_num: int, edit: bool = False):
    """Отправляет или редактирует сообщение с терминами-кнопками для указанной страницы."""
    
    if page_num < 1 or page_num > TOTAL_PAGES:
        page_num = 1
        
    text = f"Страница {page_num} из {TOTAL_PAGES}.\nВыберите термин, с которым вы хотите познакомиться:"
    
    keyboard = get_terms_page_keyboard(page_num)
    
    if edit:
        await message.edit_text(text, reply_markup=keyboard, parse_mode="HTML")
    else:
        await message.answer(text, reply_markup=keyboard, parse_mode="HTML")
    
    await state.update_data(current_page=page_num)
    await state.set_state(UserStates.terms_menu)


# --- 6. Основная логика (Хэндлеры) ---

@router.message(CommandStart())
async def cmd_start(message: Message, state: FSMContext):
    await state.clear()
    await message.answer("Добро пожаловать!\n В наш телеграм бот. \n Здесь вы сможете легко и понятно изучить важные термины и узнать, как правильно действовать в непростых ситуациях.  ", reply_markup=MAIN_MENU_KEYBOARD)


# ==========================================
# 🎁 ЛОГИКА РАЗДЕЛА: Познакомиться с терминами (КНОПКИ С ПАГИНАЦИЕЙ)
# ==========================================

@router.message(F.text == "Познакомиться с терминами")
async def start_terms_menu(message: Message, state: FSMContext):
    await send_terms_page(message, state, 1) # Отправляем первую страницу

@router.callback_query(F.data.startswith("terms_page:"), UserStates.terms_menu)
async def navigate_terms_page(callback: CallbackQuery, state: FSMContext):
    """Обработка кнопок "Вперед" и "Назад"."""
    try:
        page_num = int(callback.data.split(":")[1])
        await send_terms_page(callback.message, state, page_num, edit=True)
    except ValueError:
        await callback.answer("Ошибка в номере страницы.")
    
    await callback.answer()

@router.callback_query(F.data.startswith("term:"), UserStates.terms_menu)
async def show_term_definition(callback: CallbackQuery, state: FSMContext):
    """Обработка нажатия на кнопку с термином."""
    term_name = callback.data.split(":", 1)[1]
    definition = TERMS_DATA.get(term_name, "Определение не найдено.")
    
    # Формируем текст ответа
    text = f"📘 <b>{term_name}</b>\n\n{definition}"
    
    # Кнопка для возврата на страницу пагинации
    builder = InlineKeyboardBuilder()
    data = await state.get_data()
    current_page = data.get('current_page', 1)
    
    # Кнопка для возврата на текущую страницу
    builder.row(InlineKeyboardButton(text="↩️ Назад к списку", callback_data=f"terms_page:{current_page}"))
    
    await callback.message.edit_text(text, reply_markup=builder.as_markup(), parse_mode="HTML")
    await callback.answer()

@router.callback_query(F.data == "terms_exit", UserStates.terms_menu)
async def exit_terms_menu(callback: CallbackQuery, state: FSMContext):
    """Выход из меню терминов в главное меню."""
    await state.clear()
    await callback.message.delete()
    await callback.message.answer("Вы вернулись в главное меню.", reply_markup=MAIN_MENU_KEYBOARD)
    await callback.answer()

@router.callback_query(F.data == "ignore")
async def ignore_callback(callback: CallbackQuery):
    """Просто заглушка для некликабельных кнопок-индикаторов."""
    await callback.answer()

# ==========================================
# ЛОГИКА РАЗДЕЛА "ОБЩИЙ" (Карточки) - Без изменений
# ==========================================
# (Вся логика для General_learning, gen_yes, gen_no, gen_next, gen_exit остается прежней)
@router.message(F.text == "Общий")
async def start_general_mode(message: Message, state: FSMContext):
    terms_list = TERMS_KEYS
    await state.set_state(UserStates.general_learning)
    await state.update_data(terms_list=terms_list, current_index=0)
    await send_term_card(message, state)

async def send_term_card(message: Message, state: FSMContext):
    data = await state.get_data()
    terms_list = data.get('terms_list')
    index = data.get('current_index')
    
    if index >= len(terms_list):
        await message.answer("🎉 Вы прошли все термины!", reply_markup=MAIN_MENU_KEYBOARD)
        await state.clear()
        return

    term_name = terms_list[index]
    total = len(terms_list)
    text = f"Термин {index + 1} из {total}:\n\nЗнакомы ли вы с термином: <b>{term_name}</b>?"
    
    builder = InlineKeyboardBuilder()
    builder.row(InlineKeyboardButton(text="Да", callback_data="gen_yes"), InlineKeyboardButton(text="Нет", callback_data="gen_no"))
    builder.row(InlineKeyboardButton(text="Вернуться в меню", callback_data="gen_exit"))
    
    await message.answer(text, reply_markup=builder.as_markup(), parse_mode="HTML")

@router.callback_query(F.data == "gen_yes", UserStates.general_learning)
async def general_yes_handler(callback: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    new_index = data.get('current_index') + 1
    await state.update_data(current_index=new_index)
    await callback.message.delete()
    await send_term_card(callback.message, state)
    await callback.answer()

@router.callback_query(F.data == "gen_no", UserStates.general_learning)
async def general_no_handler(callback: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    terms_list = data.get('terms_list')
    index = data.get('current_index')
    term_name = terms_list[index]
    definition = TERMS_DATA.get(term_name, "Определение не найдено.")
    
    text = f"📖 <b>{term_name}</b>\n\n{definition}"
    
    builder = InlineKeyboardBuilder()
    builder.button(text="Далее ➡️", callback_data="gen_next")
    
    await callback.message.edit_text(text, reply_markup=builder.as_markup(), parse_mode="HTML")
    await callback.answer()

@router.callback_query(F.data == "gen_next", UserStates.general_learning)
async def general_next_handler(callback: CallbackQuery, state: FSMContext):
    await general_yes_handler(callback, state)

@router.callback_query(F.data == "gen_exit")
async def general_exit_handler(callback: CallbackQuery, state: FSMContext):
    await state.clear()
    await callback.message.delete()
    await callback.message.answer("Вы вернулись в главное меню.", reply_markup=MAIN_MENU_KEYBOARD)
    await callback.answer()
