async def start_quiz(message: Message, state: FSMContext, quiz_data: list):
    await state.set_state(UserStates.quiz_running)
    await state.update_data(quiz_data=quiz_data, current_index=0, score=0)
    await send_quiz_question(message, quiz_data, 0)

@router.message(F.text == "Юридический")
async def start_legal(message: Message, state: FSMContext):
    await start_quiz(message, state, LEGAL_QUIZ)

@router.message(F.text == "Медицинский")
async def start_medical(message: Message, state: FSMContext):
    await start_quiz(message, state, MEDICAL_QUIZ)

async def send_quiz_question(message: Message, quiz_data: list, index: int):
    if index >= len(quiz_data):
        await message.answer("🏁 Тест завершен! Выберите раздел в меню.", reply_markup=MAIN_MENU_KEYBOARD)
        return

    q_data = quiz_data[index]
    text = f"❓ <b>Вопрос {index + 1}/{len(quiz_data)}:</b>\n\n{q_data['question']}"
    
    builder = InlineKeyboardBuilder()
    for i, (option_text, _) in enumerate(q_data['options'].items()):
        builder.button(text=option_text, callback_data=f"quiz:{i}")
    
    builder.adjust(1)
    builder.row(InlineKeyboardButton(text="❌ Выход", callback_data="quit_quiz"))
    
    await message.answer(text, reply_markup=builder.as_markup(), parse_mode="HTML")

@router.callback_query(F.data.startswith("quiz:"), UserStates.quiz_running)
async def check_quiz_answer(callback: CallbackQuery, state: FSMContext):
    ans_idx = int(callback.data.split(":")[1])
    data = await state.get_data()
    quiz_data = data['quiz_data']
    idx = data['current_index']
    
    q_data = quiz_data[idx]
    options = list(q_data['options'].items())
    selected_text, selected_info = options[ans_idx]
    
    is_correct = selected_info['correct']
    info_text = selected_info['info']
    
    res_text = f"<b>{q_data['question']}</b>\n\n"
    if is_correct:
        res_text += f"✅ <b>Ответ:</b> {selected_text}\n👏 Верно!\n\n{info_text}"
    else:
        res_text += f"❌ <b>Ответ:</b> {selected_text}\n😔 Ошибка.\n\n{info_text}"
        
    builder = InlineKeyboardBuilder()
    builder.button(text="Далее ➡️", callback_data="quiz_next")
    
    await callback.message.edit_text(res_text, reply_markup=builder.as_markup(), parse_mode="HTML")
    await callback.answer()

@router.callback_query(F.data == "quiz_next", UserStates.quiz_running)
async def next_quiz_question(callback: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    new_index = data['current_index'] + 1
    await state.update_data(current_index=new_index)
    await send_quiz_question(callback.message, data['quiz_data'], new_index)
    await callback.answer()

@router.callback_query(F.data == "quit_quiz")
async def quit_quiz(callback: CallbackQuery, state: FSMContext):
    await state.clear()
    await callback.message.edit_text("Викторина остановлена.")
    await callback.message.answer("Главное меню", reply_markup=MAIN_MENU_KEYBOARD)
    await callback.answer()

@router.message(F.text == "Помощь")
async def help_handler(message: Message):
    await message.answer("Бот для проверки знаний. Выберите раздел ниже.", reply_markup=MAIN_MENU_KEYBOARD)

# --- ЗАПУСК ---

async def main():
    await bot.delete_webhook(drop_pending_updates=True)
    await dp.start_polling(bot)

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:

        print("Бот остановлен")
